type CatalogData = {
  tables: SqliteSchemaCatalog["tables"];
  catalogs: Record<string, { tables: number[]; views: SqliteSchemaCatalog["views"] }>;
};
let data: CatalogData | undefined;

export function readSqliteAgentFingerprint(hash: string): GeneratedSqliteFingerprint | undefined {
  const reference = fingerprints[hash];
  if (!reference) {
    return undefined;
  }
  const [id, fingerprint, tables, viewNames] = reference;
  return {
    id,
    fingerprint,
    viewNames,
    tableNames: tables.map((index) => tableNames[index]![0]),
    indexNames: tables.flatMap((index) => tableNames[index]![1]),
  };
}

export function readSqliteAgentCatalog(hash: string): SqliteSchemaCatalog | undefined {
  if (!fingerprints[hash]) {
    return undefined;
  }
  // Module loading keeps lazy assets on the updater's retained generation after activation.
  data ??= createRequire(import.meta.url)("./sqlite-agent-catalogs.json") as CatalogData; // SAFETY: Emitted with this loader from typed native catalog facts.
  const catalog = data.catalogs[hash]!;
  return { tables: catalog.tables.map((index) => data!.tables[index]!), views: catalog.views };
}
